insert into public.topics (module_id, slug, title, summary, position, published) select id, 'introduction-to-web-development', 'Introduction to Web Development', 'What web development is, the roles involved, and how a beginner becomes a web developer.', 0, true from public.modules where level_id = 1 and title = 'Web Foundations' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain introduction to web development in your own words.","Recognise and apply: a web developer builds and maintains websites and web applications.","Recognise and apply: the web runs on clients (browsers) and servers that respond to requests.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers introduction to web development: what web development is, the roles involved, and how a beginner becomes a web developer. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that a web developer builds and maintains websites and web applications. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that the web runs on clients (browsers) and servers that respond to requests. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how introduction to web development fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'html', '<!-- A first web page -->
