insert into public.topics (module_id, slug, title, summary, position, published) select id, 'how-the-internet-and-websites-work', 'How the Internet and Websites Work', 'How browsers, servers, DNS, HTTP and hosting deliver a website to a screen.', 0, true from public.modules where level_id = 1 and title = 'Web Foundations' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain how the internet and websites work in your own words.","Recognise and apply: DNS turns a domain name into the IP address of a server.","Recognise and apply: HTTP/HTTPS is the protocol a browser uses to request a page.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers how the internet and websites work: how browsers, servers, DNS, HTTP and hosting deliver a website to a screen. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that DNS turns a domain name into the IP address of a server. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that HTTP/HTTPS is the protocol a browser uses to request a page. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how how the internet and websites work fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'html', '<!-- The browser requests this file from a server -->
