insert into public.topics (module_id, slug, title, summary, position, published) select id, 'frontend-vs-backend-development', 'Frontend vs Backend Development', 'The difference between what users see and the logic and data behind it.', 0, true from public.modules where level_id = 1 and title = 'Web Foundations' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain frontend vs backend development in your own words.","Recognise and apply: frontend code runs in the browser and builds the interface.","Recognise and apply: backend code runs on a server and handles data, rules and storage.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers frontend vs backend development: the difference between what users see and the logic and data behind it. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that frontend code runs in the browser and builds the interface. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that backend code runs on a server and handles data, rules and storage. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how frontend vs backend development fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', '// Frontend: what the user sees and clicks
