insert into public.topics (module_id, slug, title, summary, position, published) select id, 'html-fundamentals', 'HTML Fundamentals', 'The purpose of HTML, tags, elements and attributes.', 0, true from public.modules where level_id = 1 and title = 'HTML Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain html fundamentals in your own words.","Recognise and apply: HTML gives a page its structure and meaning, not its appearance.","Recognise and apply: every element has an opening tag, content and (usually) a closing tag.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers html fundamentals: the purpose of HTML, tags, elements and attributes. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that HTML gives a page its structure and meaning, not its appearance. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that every element has an opening tag, content and (usually) a closing tag. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how html fundamentals fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'html', '<p title="A helpful hint">HTML describes <strong>structure</strong>.</p>
