insert into public.topics (module_id, slug, title, summary, position, published) select id, 'html-document-structure', 'HTML Document Structure', 'The required skeleton of every HTML document.', 0, true from public.modules where level_id = 1 and title = 'HTML Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain html document structure in your own words.","Recognise and apply: the doctype declares the document as HTML5.","Recognise and apply: head holds metadata and title; body holds visible content.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers html document structure: the required skeleton of every HTML document. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that the doctype declares the document as HTML5. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that head holds metadata and title; body holds visible content. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how html document structure fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'html', '<!DOCTYPE html>
