insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain headings, paragraphs and text formatting in your own words.","Recognise and apply: use one h1 per page, then h2 and h3 in a logical order.","Recognise and apply: strong and em add meaning; b and i only change appearance.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers headings, paragraphs and text formatting: how to organise text with headings, paragraphs and inline formatting. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that use one h1 per page, then h2 and h3 in a logical order. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that strong and em add meaning; b and i only change appearance. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how headings, paragraphs and text formatting fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'html', '<h1>Web Development</h1>
