insert into public.topics (module_id, slug, title, summary, position, published) select id, 'links-and-images', 'Links and Images', 'How to link pages and embed images accessibly.', 0, true from public.modules where level_id = 1 and title = 'HTML Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain links and images in your own words.","Recognise and apply: an anchor''s href is its destination; text should describe where it goes.","Recognise and apply: an image needs src and a meaningful alt description.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers links and images: how to link pages and embed images accessibly. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that an anchor''s href is its destination; text should describe where it goes. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that an image needs src and a meaningful alt description. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how links and images fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'html', '<a href="/curriculum">See the curriculum</a>
