insert into public.topics (module_id, slug, title, summary, position, published) select id, 'lists-and-tables', 'Lists and Tables', 'When to use ordered, unordered and description lists, and how to build a readable table.', 0, true from public.modules where level_id = 1 and title = 'HTML Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain lists and tables in your own words.","Recognise and apply: ul is for unordered items; ol is for steps or ranked items.","Recognise and apply: a table needs th header cells so rows make sense.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers lists and tables: when to use ordered, unordered and description lists, and how to build a readable table. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that ul is for unordered items; ol is for steps or ranked items. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that a table needs th header cells so rows make sense. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how lists and tables fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'html', '<ol><li>Register</li><li>Pay</li><li>Activate</li></ol>
