insert into public.topics (module_id, slug, title, summary, position, published) select id, 'semantic-html', 'Semantic HTML', 'Using meaningful elements (header, nav, main, article, footer) instead of divs everywhere.', 0, true from public.modules where level_id = 1 and title = 'HTML Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain semantic html in your own words.","Recognise and apply: semantic elements describe the role of content to browsers and assistive tools.","Recognise and apply: a page should have one main landmark containing its primary content.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers semantic html: using meaningful elements (header, nav, main, article, footer) instead of divs everywhere. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that semantic elements describe the role of content to browsers and assistive tools. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that a page should have one main landmark containing its primary content. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how semantic html fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'html', '<header><nav><a href="/">Home</a></nav></header>
