insert into public.topics (module_id, slug, title, summary, position, published) select id, 'flexbox', 'Flexbox', 'One-dimensional layout with flex containers and items.', 0, true from public.modules where level_id = 1 and title = 'CSS Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain flexbox in your own words.","Recognise and apply: display: flex turns a container into a flexible row or column.","Recognise and apply: justify-content aligns items along the main axis; align-items along the cross axis.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers flexbox: one-dimensional layout with flex containers and items. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that display: flex turns a container into a flexible row or column. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that justify-content aligns items along the main axis; align-items along the cross axis. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how flexbox fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'css', '.row { display: flex; gap: 16px; justify-content: space-between; align-items: center; }', 'Work through the example line by line. It demonstrates one-dimensional layout with flex containers and items. The first lines set up the context; the middle lines do the main work described by the two key ideas above; the final lines produce the result you can check in a browser, editor or terminal. Change one value, re-run it, and confirm that the change behaves as you predicted — that check is the real learning.', 'Build a small, real example of flexbox: one-dimensional layout with flex containers and items. Use the code example as a starting point, change it to fit your own example, and check that it works. Write down one thing that surprised you and one thing you would do differently next time. You may not mark this topic complete until you have finished the lesson and passed its quiz (7/10).', '[{"mistake":"Skipping the idea and copying the code example without understanding it.","correction":"Read each line, change one thing, and observe what changes. Understanding survives; copying does not."},{"mistake":"Treating flexbox as a fact to memorise instead of a skill to practise.","correction":"Practise on a small real example the same day. A topic is only complete after its lesson and a passed quiz (7/10)."},{"mistake":"Ignoring error messages and warnings while working on flexbox.","correction":"Read the message, note the file and line, and fix the named problem before moving on."}]'::jsonb, 'In short: Flexbox is about one-dimensional layout with flex containers and items. Remember that display: flex turns a container into a flexible row or column, and that justify-content aligns items along the main axis; align-items along the cross axis. Practise it on a real example, check your work, and then take the 10-question quiz — 7 correct answers passes the topic.', 1 from public.topics where slug = 'flexbox' on conflict (topic_id, version) do nothing;
