insert into public.topics (module_id, slug, title, summary, position, published) select id, 'introduction-to-javascript', 'Introduction to JavaScript', 'What JavaScript adds to a page and how it runs in the browser.', 0, true from public.modules where level_id = 1 and title = 'JavaScript Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain introduction to javascript in your own words.","Recognise and apply: JavaScript adds behaviour: responding to clicks, changing content, fetching data.","Recognise and apply: a script tag or external .js file loads code after the HTML it touches.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers introduction to javascript: what JavaScript adds to a page and how it runs in the browser. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that JavaScript adds behaviour: responding to clicks, changing content, fetching data. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that a script tag or external .js file loads code after the HTML it touches. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how introduction to javascript fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', '// JavaScript runs in the browser
