insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain dom manipulation in your own words.","Recognise and apply: the DOM is the browser''s live tree of the page''s elements.","Recognise and apply: querySelector finds an element; textContent and classList change it safely.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers dom manipulation: reading and changing the page with the Document Object Model. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that the DOM is the browser''s live tree of the page''s elements. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that querySelector finds an element; textContent and classList change it safely. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how dom manipulation fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'const title = document.querySelector(''#lesson-title'');
