insert into public.topics (module_id, slug, title, summary, position, published) select id, 'advanced-html-and-accessibility', 'Advanced HTML and Accessibility', 'Accessible markup: landmarks, labels, alt text, keyboard support and ARIA where needed.', 0, true from public.modules where level_id = 2 and title = 'Advanced HTML & CSS' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain advanced html and accessibility in your own words.","Recognise and apply: alt text must describe an image''s purpose, not just say ''image''.","Recognise and apply: form controls need labels; keyboard users must reach every action.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers advanced html and accessibility: accessible markup: landmarks, labels, alt text, keyboard support and ARIA where needed. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that alt text must describe an image''s purpose, not just say ''image''. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that form controls need labels; keyboard users must reach every action. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how advanced html and accessibility fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'html', '<button aria-label="Close menu">×</button>
