insert into public.topics (module_id, slug, title, summary, position, published) select id, 'responsive-layout-architecture', 'Responsive Layout Architecture', 'Planning layouts mobile-first with breakpoints and fluid containers.', 0, true from public.modules where level_id = 2 and title = 'Advanced HTML & CSS' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain responsive layout architecture in your own words.","Recognise and apply: mobile-first means the base styles target small screens, then larger screens add rules.","Recognise and apply: a max-width container with auto margins centres content on wide screens.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers responsive layout architecture: planning layouts mobile-first with breakpoints and fluid containers. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that mobile-first means the base styles target small screens, then larger screens add rules. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that a max-width container with auto margins centres content on wide screens. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how responsive layout architecture fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'css', '.container { width: 100%; max-width: 1100px; margin: 0 auto; padding: 0 16px; }
