insert into public.topics (module_id, slug, title, summary, position, published) select id, 'advanced-flexbox-and-grid', 'Advanced Flexbox and Grid', 'Flex-grow/shrink/basis, wrapping, alignment and grid areas.', 0, true from public.modules where level_id = 2 and title = 'Advanced HTML & CSS' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain advanced flexbox and grid in your own words.","Recognise and apply: flex: 1 lets an item grow to fill spare space.","Recognise and apply: grid-template-areas names regions so layout reads like a map.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers advanced flexbox and grid: flex-grow/shrink/basis, wrapping, alignment and grid areas. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that flex: 1 lets an item grow to fill spare space. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that grid-template-areas names regions so layout reads like a map. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how advanced flexbox and grid fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'css', '.app { display: grid; grid-template-areas: ''nav main'' ''nav main''; grid-template-columns: 220px 1fr; }
