insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain dom events and advanced manipulation in your own words.","Recognise and apply: events bubble up, so one listener on a parent can handle many children.","Recognise and apply: createElement + appendChild builds DOM from data instead of long HTML strings.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers dom events and advanced manipulation: event delegation, bubbling, and building elements from data. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that events bubble up, so one listener on a parent can handle many children. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that createElement + appendChild builds DOM from data instead of long HTML strings. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how dom events and advanced manipulation fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'const list = document.querySelector(''#topics'');
