insert into public.topics (module_id, slug, title, summary, position, published) select id, 'github-fundamentals', 'GitHub Fundamentals', 'Remote repositories, pushing, pulling and pull requests on GitHub.', 0, true from public.modules where level_id = 2 and title = 'Git & GitHub' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain github fundamentals in your own words.","Recognise and apply: origin is the remote copy; push sends commits, pull brings them down.","Recognise and apply: a pull request proposes changes for review before merging.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers github fundamentals: remote repositories, pushing, pulling and pull requests on GitHub. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that origin is the remote copy; push sends commits, pull brings them down. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that a pull request proposes changes for review before merging. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how github fundamentals fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'bash', 'git remote add origin https://github.com/Oluwadarasimi-Official/nexora-web-dev-academy.git
