insert into public.topics (module_id, slug, title, summary, position, published) select id, 'version-control', 'Version Control', 'Branching strategy, merge conflicts and a clean history.', 0, true from public.modules where level_id = 2 and title = 'Git & GitHub' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain version control in your own words.","Recognise and apply: commit small, working changes with messages that say why, not just what.","Recognise and apply: resolve a merge conflict by choosing the correct lines, then commit the result.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers version control: branching strategy, merge conflicts and a clean history. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that commit small, working changes with messages that say why, not just what. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that resolve a merge conflict by choosing the correct lines, then commit the result. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how version control fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'bash', 'git checkout -b feature/quiz-page
