insert into public.topics (module_id, slug, title, summary, position, published) select id, 'routing', 'Routing', 'Client-side routing in single-page apps and in Next.js.', 0, true from public.modules where level_id = 2 and title = 'React' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain routing in your own words.","Recognise and apply: routing maps a URL to a screen without a full page reload.","Recognise and apply: in Next.js, a folder under app/ becomes a route automatically.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers routing: client-side routing in single-page apps and in Next.js. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that routing maps a URL to a screen without a full page reload. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that in Next.js, a folder under app/ becomes a route automatically. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how routing fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', '// Next.js App Router: src/app/dashboard/page.tsx  ->  /dashboard
