insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain intermediate practical project in your own words.","Recognise and apply: break the app into components first, then wire data and state.","Recognise and apply: loading, empty and error states are part of the product, not extras.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers intermediate practical project: a complete intermediate project with reusable components, responsive UI and an external API. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that break the app into components first, then wire data and state. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that loading, empty and error states are part of the product, not extras. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how intermediate practical project fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', '// Project: a lesson browser that fetches topics from an API
