insert into public.topics (module_id, slug, title, summary, position, published) select id, 'advanced-react-architecture', 'Advanced React Architecture', 'Patterns for larger apps: custom hooks, context, and separating concerns.', 0, true from public.modules where level_id = 3 and title = 'Advanced JS, TypeScript & Next.js' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain advanced react architecture in your own words.","Recognise and apply: a custom hook extracts reusable stateful logic from components.","Recognise and apply: context shares data (like the logged-in student) without prop drilling.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers advanced react architecture: patterns for larger apps: custom hooks, context, and separating concerns. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that a custom hook extracts reusable stateful logic from components. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that context shares data (like the logged-in student) without prop drilling. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how advanced react architecture fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'typescript', 'import { createContext, useContext } from ''react'';
