insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain routing and server rendering in your own words.","Recognise and apply: a [slug] folder creates a dynamic route for many pages from one file.","Recognise and apply: loading.tsx shows a loading state while a route prepares.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers routing and server rendering: dynamic routes, layouts, loading states and metadata in Next.js. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that a [slug] folder creates a dynamic route for many pages from one file. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that loading.tsx shows a loading state while a route prepares. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how routing and server rendering fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'typescript', '// src/app/dashboard/topic/[slug]/page.tsx
