insert into public.topics (module_id, slug, title, summary, position, published) select id, 'authentication-and-authorization', 'Authentication and Authorization', 'Proving who you are, and what you are allowed to do.', 0, true from public.modules where level_id = 3 and title = 'Auth, Security & Supabase' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain authentication and authorization in your own words.","Recognise and apply: authentication answers ''who are you?''; authorization answers ''what may you do?''.","Recognise and apply: check the role on the server on every privileged request — never in the browser alone.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers authentication and authorization: proving who you are, and what you are allowed to do. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that authentication answers ''who are you?''; authorization answers ''what may you do?''. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that check the role on the server on every privileged request — never in the browser alone. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how authentication and authorization fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'typescript', '// Server-side: read the session, then check user_roles.
