insert into public.topics (module_id, slug, title, summary, position, published) select id, 'supabase-integration', 'Supabase Integration', 'Using Supabase Auth, Postgres and storage from a Next.js app.', 0, true from public.modules where level_id = 3 and title = 'Auth, Security & Supabase' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain supabase integration in your own words.","Recognise and apply: the Supabase client uses the project URL and publishable key from env vars.","Recognise and apply: server clients read the session from cookies; browser clients use local storage.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers supabase integration: using Supabase Auth, Postgres and storage from a Next.js app. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that the Supabase client uses the project URL and publishable key from env vars. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that server clients read the session from cookies; browser clients use local storage. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how supabase integration fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'typescript', 'import { createClient } from ''@supabase/supabase-js'';
