insert into public.topics (module_id, slug, title, summary, position, published) select id, 'full-stack-application-development', 'Full-Stack Application Development', 'Bringing it together: a complete app from database to deployed UI.', 0, true from public.modules where level_id = 3 and title = 'Performance, SEO & Production' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain full-stack application development in your own words.","Recognise and apply: a full-stack feature touches schema, API, UI and tests together.","Recognise and apply: ship in small, verified slices; never claim a slice works until it is tested live.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers full-stack application development: bringing it together: a complete app from database to deployed UI. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that a full-stack feature touches schema, API, UI and tests together. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that ship in small, verified slices; never claim a slice works until it is tested live. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how full-stack application development fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'typescript', '// Slice example: payment submission
