insert into public.examinations (level_id, title, duration_minutes, pass_mark_percent, instructions, rubric) values (1, 'Beginner Final Examination', 60, 70, 'Answer all objective questions and all theory questions. The objective section is marked automatically on the server. Theory answers are graded by an authorised examiner against the published rubric and marked as pending until graded. You must score at least 70% overall and have your theory grading completed to pass. Do not refresh or close the page during the examination; your start time is recorded on the server and the timer is enforced server-side.', 'Theory rubric (each theory question, 10 marks): understanding of the concept (4), correct use of terminology and examples (3), clarity and structure of the answer (2), practical application or correct code where asked (1). Total 30 theory marks + 20 objective marks (1 each) = 50. Pass mark 70% (35/50).') on conflict (level_id) do nothing;
insert into public.examinations (level_id, title, duration_minutes, pass_mark_percent, instructions, rubric) values (2, 'Intermediate Final Examination', 75, 70, 'Answer all objective questions and all theory questions. The objective section is marked automatically on the server. Theory answers are graded by an authorised examiner against the published rubric and marked as pending until graded. You must score at least 70% overall and have your theory grading completed to pass. Do not refresh or close the page during the examination; your start time is recorded on the server and the timer is enforced server-side.', 'Theory rubric (each theory question, 10 marks): understanding of the concept (4), correct use of terminology and examples (3), clarity and structure of the answer (2), practical application or correct code where asked (1). Total 30 theory marks + 20 objective marks (1 each) = 50. Pass mark 70% (35/50).') on conflict (level_id) do nothing;
